mkdir -p .railway && cat > .railway/railway.ts <<'EOF'
// Railway Infrastructure as Code for this app (replaces railway.toml, which
// Railway stops reading on 2026-12-01).
//
//   cd .railway && npm install      # installs the `railway` SDK for types
//   railway login && railway link   # from the repo root
//   railway config plan             # preview
//   railway config apply            # create/update the project
//
// This file is declarative: variables that are not listed here are removed on
// `apply`. Set secrets in the Railway dashboard and keep them listed below
// with `preserve()` so apply leaves their values alone.
import { defineRailway, github, postgres, preserve, project, service } from "railway/iac";

export default defineRailway(() => {
  const db = postgres("postgres");

  const api = service("api", {
    source: github("albertogrande/fastapi_production_template", { branch: "main" }),
    build: { builder: "DOCKERFILE", dockerfilePath: "Dockerfile.prod" },
    start: "entrypoints/gunicorn.sh",
    // Fails the deploy (and keeps the previous one live) if migrations fail.
    preDeploy: "alembic upgrade head",
    healthcheck: "/healthcheck",
    healthcheckTimeout: 120,
    deploy: {
      restartPolicyType: "ON_FAILURE",
      restartPolicyMaxRetries: 5,
      // Serverless: the container stops after ~10 min without outbound traffic
      // and wakes on the next request (a few seconds of cold start). You are
      // not billed for CPU/RAM while it sleeps.
      sleepApplication: true,
    },
    env: {
      ENVIRONMENT: "PRODUCTION",
      // Private-network URL; the asyncpg URL is derived from it in src/config.py.
      DATABASE_URL: db.env.DATABASE_URL,
      // gunicorn sizes workers from the CPU count, which on Railway is the
      // host's (dozens of cores) and would blow past the memory limit.
      WEB_CONCURRENCY: "2",
      DATABASE_POOL_SIZE: "5",
      // Required when ENVIRONMENT is PRODUCTION (see src/config.py). Set it in
      // the dashboard; a free Sentry Developer plan is enough.
      SENTRY_DSN: preserve(),
    },
  });

  return project("fastapi-production-template", { resources: [db, api] });
});
EOF
